  ('cocopah-bend-rv-and-golf-resort', 'Cocopah Bend RV and Golf Resort', 'Yuma', 'AZ', array[3,4,4,3,5,4,4,5,4,3,4,5,4,3,4,4,4,5]::int[], array[17,3,7,15,1,11,9,5,13,10,12,2,16,18,8,14,4,6]::int[]),
  ('mount-graham-golf-club', 'Mount Graham Golf Club', 'Safford', 'AZ', array[4,5,4,4,4,4,3,4,4,4,5,4,3,5,4,4,3,4]::int[], array[15,11,13,3,1,5,17,9,7,16,2,12,18,6,8,10,14,4]::int[])
), upserted_courses as (
  select 'csv_seed', course_key, course_name, lower(regexp_replace(course_name, '[^a-z0-9]+', '-', 'g')), city, state from course_seed
  on conflict (normalized_name, city, state) do update set source_provider = excluded.source_provider, source_course_id = excluded.source_course_id, updated_at = now()
  returning id, source_course_id
), hole_seed as (
  select uc.id as saved_course_id, hole_number, pars[hole_number] as par, hcps[hole_number] as handicap_index
  from course_seed cs join upserted_courses uc on uc.source_course_id = cs.course_key cross join generate_series(1,18) as hole_number
)
select saved_course_id, hole_number, par, handicap_index from hole_seed
on conflict (saved_course_id, hole_number) do update set par = excluded.par, handicap_index = excluded.handicap_index, updated_at = now();

